import React from "react";
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, Legend } from "recharts";

const SEVERITY_COLORS = {
  high: "#ff3366",   // Electric Crimson / Neon Pink - Fighting against the blues
  medium: "#f59e0b", // Cyber Amber
  low: "#00f2fe",    // Neon Cyan
};

export default function SeverityPieChart({ alerts = [] }) {
  const safeAlerts = Array.isArray(alerts) ? alerts : [];

  const counts = safeAlerts.reduce(
    (acc, alert) => {
      const sev = (alert.severity || "low").toLowerCase();
      if (acc[sev] !== undefined) {
        acc[sev] += 1;
      } else {
        acc.low += 1;
      }
      return acc;
    },
    { high: 0, medium: 0, low: 0 }
  );

  const data = [
    { name: "High Severity", value: counts.high, color: SEVERITY_COLORS.high },
    { name: "Medium Severity", value: counts.medium, color: SEVERITY_COLORS.medium },
    { name: "Low Severity", value: counts.low, color: SEVERITY_COLORS.low },
  ].filter((item) => item.value > 0);

  if (safeAlerts.length === 0 || data.length === 0) {
    return (
      <div style={{ height: 260, display: "flex", alignItems: "center", justifyContent: "center", color: "#868e96", fontSize: "0.9rem" }}>
        No alert data for distribution yet
      </div>
    );
  }

  return (
    <div style={{ width: "100%", height: 260 }}>
      <ResponsiveContainer width="100%" height="100%">
        <PieChart>
          <Pie
            data={data}
            cx="50%"
            cy="50%"
            innerRadius={55}
            outerRadius={85}
            paddingAngle={4}
            dataKey="value"
          >
            {data.map((entry, index) => (
              <Cell key={`cell-${index}`} fill={entry.color} />
            ))}
          </Pie>
          <Tooltip
            formatter={(value, name) => [`${value} alerts`, name]}
            contentStyle={{ backgroundColor: "#141c2e", borderColor: "#2d3748", color: "#e2e8f0", borderRadius: "8px", boxShadow: "0 4px 12px rgba(0,0,0,0.5)" }}
          />
          <Legend verticalAlign="bottom" height={36} iconType="circle" wrapperStyle={{ color: "#a0aec0", fontSize: "0.85rem" }} />
        </PieChart>
      </ResponsiveContainer>
    </div>
  );
}
